props.description:
Size within the active type scale. Responsive object syntax supported.
Heading sizes: xs | sm | md | lg | xl | xxl
Display sizes: sm | md | lg | xl | xxl | jumbo | xJumbo
@example size={{ xs: "lg", md: "xl" }}

@deprecated Accepted but ignored. Snackbar has a single visual style; use
`Banner` for persistent status-coloured messages. Will be removed in a
future major version.

Flex direction. Responsive object syntax supported.
Default: "column"
@example direction={{ xs: "column", md: "row" }}

Space height. Responsive object syntax supported.
xs=8px · sm=16px · md=24px · lg=40px · xl=64px · xxl=96px
Default: "md"
@example size={{ xs: "sm", md: "lg" }}

props.type:
Array<{
    key: string;
    label: string;
    searchAccessor?: (row: Record<string, unknown>) => unknown;
    /** Custom matcher for built-in search. Return true when this row should match the normalized query. */
    searchMatcher?: (row: Record<string, unknown>, query: string) => boolean;
  }>
